# abstract-name = concrete package(s) on this base
# Browser and audio firmware come from upstream forks (mod 05) until packages/ ships;
# the acceptance policy forbids the stock firefox and firmware-sof-signed packages.
browser            =
browser-esr        = firefox-esr
office             = libreoffice libreoffice-gtk4
mail               = evolution evolution-ews
firmware-audio     =
firmware-wifi      = linux-firmware
translations       = language-pack-${LANG} language-pack-${LANG}-base language-pack-gnome-${LANG} language-pack-gnome-${LANG}-base
spellcheck         = hunspell-${LANG}
# The desktop is provided by the upstream metapackage (mod 05) until packages/ ships.
gnome-desktop      =
rdp-client         = remmina remmina-plugin-rdp
vpn                = network-manager-openvpn-gnome wireguard-tools
printing           = cups printer-driver-all
smartcard          = opensc pcscd
directory          = sssd realmd adcli krb5-user libpam-sss libnss-sss oddjob-mkhomedir
hardening          = apparmor-profiles-extra ufw auditd fwupd unattended-upgrades
usbguard           = usbguard
openscap           = libopenscap8 ssg-base
containers         = podman buildah skopeo
evince             = evince
gnome-calendar     = gnome-calendar
build-essential    = build-essential
gdb                = gdb
cmake              = cmake
code-oss           = code
ssh-server         = openssh-server
web-admin          = cockpit cockpit-podman cockpit-networkmanager cockpit-storaged
virtualization     = qemu-system libvirt-daemon-system virtinst
gpu-nvidia         = nvidia-driver-580-open nvidia-cuda-toolkit nvidia-utils-580
gpu-amd            = rocminfo rocm-smi
gpu-intel          = intel-opencl-icd libze-intel-gpu1 libze1 intel-media-va-driver-non-free
ai-dev             = python3-torch python3-venv python3-pip llama.cpp
# Yocto Project reference manual, "Ubuntu and Debian" required packages, plus
# python3-websockets (needed on every supported suite but jammy/22.04, where
# the archive version is too old for BitBake's hash equivalence server; use
# a venv there instead). lz4, not the transitional liblz4-tool.
yocto-host-tools   = gawk wget git diffstat unzip texinfo build-essential chrpath socat cpio python3 python3-pip python3-pexpect xz-utils debianutils iputils-ping python3-git python3-jinja2 python3-subunit zstd lz4 file locales libacl1 libcrypt-dev gcc python3-websockets
# Practical build-host tools the manual doesn't list but a real Yocto host
# needs day to day; small enough to ship by default. Only the x86 and arm
# system emulators plus qemu-utils (not the qemu-system metapackage, which
# also pulls mips/ppc/sparc/s390x emulators for roughly 470 MB more).
yocto-practical-tools = rsync bc bison flex libssl-dev git-lfs bmap-tools pigz ccache device-tree-compiler u-boot-tools qemu-system-x86 qemu-system-arm qemu-utils
# Building the Yocto Project documentation, including PDFs (texlive is large:
# this is its own bundle so a person opts in rather than always paying for it).
yocto-doc-tools    = make librsvg2-bin python3-saneyaml python3-venv fonts-freefont-otf latexmk tex-gyre texlive-fonts-extra texlive-fonts-recommended texlive-lang-all texlive-latex-extra texlive-latex-recommended texlive-xetex
# The "test-engine" bundle (profiles/bundles.yml): everything
# packaging/install-test-engine.sh's REQUIREMENTS list installs by hand on a
# spare machine, checked here so a profile can ship the same tooling inside
# the image itself — the container runtime tools/bundle_launcher.sh builds
# in, QEMU and xorriso for the ISO boot smoke test, Tesseract and Pillow for
# its OCR check, and PyYAML for tools/catalog_conformance.py itself
# (docs/BUILD_MATRIX.md, "Installing it as a service"). python3 is listed
# explicitly because this bundle must also work on a profile with no
# desktop, where nothing else already pulls it in.
python3            = python3
pyyaml             = python3-yaml
qemu               = qemu-system-x86
xorriso            = xorriso
tesseract          = tesseract-ocr
pillow             = python3-pil
# Headless-capable Chromium/Chrome, the way tools/devtools_browser.py drives
# it (google-chrome, google-chrome-stable, chromium-browser or chromium).
# Not Ubuntu's own "chromium"/"chromium-browser": checked directly against
# archive.ubuntu.com's Packages indexes for jammy, noble and resolute, it is
# a transitional package everywhere (Pre-Depends: debconf, snapd) whose only
# job is installing the Chromium *snap* — this base ships no snapd at all
# (test_package_policy.py, FORBIDDEN_IMAGE_PACKAGES), so apt-get installing
# it would either drag snapd onto the image or fail outright. Real fixes
# checked against the archives, not from memory, before landing on this one:
# no supported Ubuntu release packages a non-snap Chromium under any name;
# Firefox's own "stock-package-is-forbidden" fix (an upstream-forked build,
# mod 05) has no Chromium equivalent shipping yet. What does exist, and is
# used here: Google's own apt repository (dl.google.com/linux/chrome/deb,
# verified reachable, dated, real .deb, ordinary Depends — no snapd) forked
# the same way packages/firefox-synos forks Firefox from Mozilla's own repo.
# packages/google-chrome-synos/fork.json fetches it and drops the upstream
# maintainer scripts and its cron auto-updater (which would otherwise
# re-register Google's apt source on every image), keeping only the real
# google-chrome-stable binary. amd64 and arm64 both exist upstream.
browser-headless   = google-chrome-synos
# Bundle-catalog workstation appliances (docs/BUNDLE.md, "The bundle
# catalog"): each catalogued bundle pins one base and one suite in its own
# manifest, so a package below only has to exist on that entry's suite,
# checked with rmadison against that suite specifically (noted per group);
# it need not exist on every suite this base supports.
# audio-workstation targets noble: PipeWire's JACK compatibility layer
# (pipewire-jack, qpwgraph) is on noble/resolute but missing from jammy,
# so a jammy-based derived profile using this group would need jackd2/
# qjackctl instead.
audio-production-tools = ardour pipewire-jack qpwgraph a2jmidid jack-mixer calf-plugins x42-plugins lsp-plugins-jack hydrogen guitarix rakarrack rtkit
# video-editing-workstation targets noble.
video-editing-tools    = kdenlive ffmpeg va-driver-all vainfo mesa-va-drivers vdpau-driver-all
# photography-workstation targets noble (displaycal is missing from jammy).
photography-tools      = darktable rawtherapee argyll gphoto2 displaycal
# cad-3d-printing-workstation targets Debian trixie instead (see
# bases/debian/packages.map): FreeCAD and Cura are missing from noble and
# resolute, so the Ubuntu side of this group stays the OpenSCAD/PrusaSlicer
# set, which is available on every Ubuntu suite this engine supports.
cad-3d-printing-tools  = openscad prusa-slicer
data-science-tools     = jupyter-notebook python3-numpy python3-scipy python3-pandas python3-matplotlib python3-sklearn python3-seaborn
security-research-tools = nmap wireshark tcpdump aircrack-ng sqlmap nikto hydra john hashcat gobuster whatweb dirb netcat-openbsd libcap2-bin
# retro-gaming-console targets noble, which also carries Nestopia (NES) and
# Beetle PCE Fast (PC Engine/TurboGrafx-16); Beetle PCE Fast is missing
# from Debian trixie, so it is Ubuntu-only (see bases/debian/packages.map).
retro-gaming-tools     = retroarch retroarch-assets joystick jstest-gtk libretro-snes9x libretro-mgba libretro-gambatte libretro-desmume libretro-nestopia libretro-beetle-pce-fast
